namespace {
using Word=std::uint32_t;
void require(bool value,const char* message) { if(!value) throw std::runtime_error(message); }
Word address(const void* value) { return reinterpret_cast<Word>(value); }
Word word(const void* object,Word offset=0) { Word value; std::memcpy(&value,static_cast<const std::byte*>(object)+offset,4); return value; }
bsp::NativeResourceSupportStorage* volatile publication{};
void __cdecl forbidden_free(void*) { TerminateProcess(GetCurrentProcess(),51); }
void scalar_retention() {
    // Full native body, explicit publication/free bindings. flags2 never frees.
    void* code=VirtualAlloc(nullptr,sizeof original_00b61d60,MEM_COMMIT|MEM_RESERVE,PAGE_READWRITE);
    require(code!=nullptr,"native code allocation"); std::memcpy(code,original_00b61d60,sizeof original_00b61d60);
    auto* bytes=static_cast<unsigned char*>(code);
    require(word(bytes,0xa)==0x0108fedc && bytes[0x1b]==0xe8,"native binding operands");
    const Word pub=address(const_cast<bsp::NativeResourceSupportStorage**>(&publication)); std::memcpy(bytes+0xa,&pub,4);
    const Word displacement=address(reinterpret_cast<void*>(&forbidden_free))-(address(code)+0x20); std::memcpy(bytes+0x1c,&displacement,4);
    DWORD prior; require(VirtualProtect(code,sizeof original_00b61d60,PAGE_EXECUTE_READ,&prior)!=0,"native code protection");
    require(FlushInstructionCache(GetCurrentProcess(),code,sizeof original_00b61d60)!=0,"native code cache");
    struct Guarded { Word before; bsp::NativeResourceSupportStorage owner; Word after; };
    Guarded a{0x11112222,{0x00d62b64,{}},0x33334444},b=a;
    std::memset(a.owner.untouched_04,0xa6,4); b=a;
    bsp::NativeResourceSupportStorage different{0x00d62b64,{}};
    using Native=bsp::NativeResourceSupportStorage* (__fastcall*)(void*,void*,Word);
    publication=&different; require(reinterpret_cast<Native>(code)(&a.owner,nullptr,2)==&a.owner && publication==nullptr,"original scalar return/current clear");
    publication=&different; require(bsp::delete_native_resource_support_00b61d60(b.owner,2,publication)==&b.owner && publication==nullptr,"source scalar return/current clear");
    require(std::memcmp(&a,&b,sizeof a)==0 && a.owner.native_vtable_00==0x00ce3818 && different.native_vtable_00==0x00d62b64,"scalar retained storage and rebound owner");
    require(VirtualFree(code,0,MEM_RELEASE)!=0,"native code release");
}
void actual_manager_drain() {
    void* volatile manager_publication=nullptr;
    publication=nullptr;
    bsp::SoundLifetimeAccess lifetime(manager_publication);
    require(lifetime.uses_actual_storage(),"actual AA0 lifetime view");
    auto* registered=bsp::resource_support_singleton_00b3e730(publication,lifetime);
    void* const manager=manager_publication;
    require(registered && manager && publication==registered,"getter real publication");
    require(registered->native_vtable_00==0x00d62b64 && bsp::count_native_singleton_slots_00bcf910(manager,nullptr)==1,"actual registered support owner");
    require(word(reinterpret_cast<void*>(word(manager,4)))==address(registered),"actual array registered identity");
    auto* section=reinterpret_cast<bsp::TrackedCriticalSection*>(word(manager,0x10));
    require(section && section->depth==0 && section->native.RecursionCount==0,"getter real guard balanced");
    const Word manager_profile=word(manager);
    auto* replacement=bsp::construct_native_resource_support_00b61d50(bsp::singleton_lifetime_allocate({bsp::SingletonAllocationKind::object,8,8}));
    require(replacement && replacement!=registered,"distinct rebound allocation");
    std::memset(replacement->untouched_04,0x79,4);
    publication=replacement;
    bsp::NativeSingletonDeletionBindings bindings{};
    bindings.actual_resource_support_publication_0108fedc=&publication;
    bsp::destroy_native_singleton_manager_00bd0400(manager,bindings);
    require(publication==nullptr,"popped deleter clears rebound publication");
    require(manager_publication==manager && word(manager)==manager_profile,"manager allocation/publication remains caller owned");
    require(word(manager,4)==0 && word(manager,8)==0 && word(manager,12)==0 && word(manager,16)==0,"actual manager storage and section released");
    require(replacement->native_vtable_00==0x00d62b64 && word(replacement,4)==0x79797979,"rebound owner was not selected or destroyed");
    // Rebound owner was never registered; its caller retains and releases it.
    bsp::delete_native_resource_support_00b61d60(*replacement,1,publication);
    bsp::singleton_lifetime_free(manager); manager_publication=nullptr;
}
void module_record(const wchar_t* name,HMODULE module,const char* category) {
    if(!module) { std::printf("UNLOADED_RUNTIME|%ls\n",name); return; }
    wchar_t reported[1024],canonical[1024]; const DWORD n=GetModuleFileNameW(module,reported,1024); require(n&&n<1024,"module path");
    HANDLE file=CreateFileW(reported,GENERIC_READ,FILE_SHARE_READ|FILE_SHARE_WRITE|FILE_SHARE_DELETE,nullptr,OPEN_EXISTING,FILE_ATTRIBUTE_NORMAL,nullptr); require(file!=INVALID_HANDLE_VALUE,"module file");
    const DWORD m=GetFinalPathNameByHandleW(file,canonical,1024,FILE_NAME_NORMALIZED); CloseHandle(file); require(m&&m<1024,"canonical module file");
    const auto* data=reinterpret_cast<const unsigned char*>(module); const auto* dos=reinterpret_cast<const IMAGE_DOS_HEADER*>(data); const auto* nt=reinterpret_cast<const IMAGE_NT_HEADERS32*>(data+dos->e_lfanew);
    require(nt->FileHeader.Machine==IMAGE_FILE_MACHINE_I386,"loaded x86 machine"); std::printf("%s|%ls|%ls|%ls|%04x\n",category,name,reported,canonical,static_cast<unsigned>(nt->FileHeader.Machine));
}
void provider_record(const wchar_t* role,void* function) {
    HMODULE module{}; require(GetModuleHandleExW(GET_MODULE_HANDLE_EX_FLAG_FROM_ADDRESS|GET_MODULE_HANDLE_EX_FLAG_UNCHANGED_REFCOUNT,reinterpret_cast<LPCWSTR>(function),&module)!=0,"guard provider module");
    std::printf("PROVIDER_ADDRESS|%ls|%08x\n",role,address(function)); module_record(role,module,"LOADED_PROVIDER");
}
}
int main() {
    try {
        scalar_retention(); actual_manager_drain();
        for(const auto* name:{L"ucrtbase.dll",L"vcruntime140.dll",L"msvcp140.dll",L"vcruntime140_1.dll",L"kernel32.dll",L"ntdll.dll"}) module_record(name,GetModuleHandleW(name),"LOADED_RUNTIME");
        provider_record(L"EnterCriticalSection",reinterpret_cast<void*>(&EnterCriticalSection));
        provider_record(L"LeaveCriticalSection",reinterpret_cast<void*>(&LeaveCriticalSection));
