        std::puts("PASS: original/source scalar retention and actual-AA0 registered resource-support drain with rebound publication, concrete deleter and released manager storage/section");
        return 0;
    } catch(const std::exception& error) { std::fprintf(stderr,"FAIL: %s\n",error.what()); return 1; }
}

