$ErrorActionPreference = 'Stop'
$vswhere = Join-Path ${env:ProgramFiles(x86)} 'Microsoft Visual Studio/Installer/vswhere.exe'
$vsPath = & $vswhere -latest -products '*' -requires Microsoft.VisualStudio.Component.VC.Tools.x86.x64 -property installationPath
& (Join-Path $vsPath 'Common7/Tools/Launch-VsDevShell.ps1') -Arch x86 -HostArch amd64 -SkipAutomaticLocation | Out-Null
$cmakeDirectory = Join-Path $vsPath 'Common7/IDE/CommonExtensions/Microsoft/CMake/CMake/bin'
$toolPaths = @{
    compiler = (Get-Command cl.exe).Source
    linker = (Get-Command link.exe).Source
    librarian = (Get-Command lib.exe).Source
    python = (Get-Command python.exe).Source
    powershell = (Get-Process -Id $PID).Path
    cmake = (Join-Path $cmakeDirectory 'cmake.exe')
    ctest = (Join-Path $cmakeDirectory 'ctest.exe')
}
$toolRecords = foreach ($entry in $toolPaths.GetEnumerator()) {
    $item = Get-Item -LiteralPath $entry.Value
    [pscustomobject]@{ role=$entry.Key; path=$item.FullName; file_version=$item.VersionInfo.FileVersion; bytes=$item.Length }
}
[System.IO.File]::WriteAllText((Join-Path $PWD 'local/native_resource_support_drain_tools.json'),($toolRecords | ConvertTo-Json),[System.Text.UTF8Encoding]::new($false))
cl /nologo /std:c++20 /EHsc /MD /O2 /W4 /WX /fp:strict /I include /I local /Fo:local/native_resource_support_drain_probe.obj /Fe:local/native_resource_support_drain_probe.exe local/native_resource_support_drain_probe.cpp build/win32/Release/bsp_core.lib build/win32/Release/bsp_lua511.lib build/win32/Release/bsp_zlib121.lib /link /MANIFEST:EMBED user32.lib d3d9.lib shell32.lib kernel32.lib gdi32.lib winspool.lib ole32.lib oleaut32.lib uuid.lib comdlg32.lib advapi32.lib
